def transform(frame):
    change = frame['metric'].diff(1)
    return pd.DataFrame({'fe_change': change}, index=frame.index)

def transform(frame):
    gap = past.gap_seconds(frame)
    count = past.observation_count(frame)
    return pd.DataFrame({'fe_gap': gap, 'fe_count': count}, index=frame.index)

def transform(frame):
    avg = frame['metric'].rolling('7D', min_periods=1).mean()
    return pd.DataFrame({'fe_mean': avg}, index=frame.index)
